var W=320,FLOOR=458,R=10,BX=72,GAP=138,PW=52,SPACING=168,SPEED=132,GRAV=1500,FLAP=-390,t=0;
if(state.best==null||isNaN(state.best))state.best=0;
function gapRand(){var m=GAP/2+26;return m+Math.random()*(FLOOR-2*m);}
function draw(){var s='',i,p,top,bot;for(i=0;i<state.pipes.length;i++){p=state.pipes[i];top=p.gap-GAP/2;bot=p.gap+GAP/2;s+='<rect x="'+p.x.toFixed(1)+'" y="0" width="'+PW+'" height="'+top.toFixed(1)+'" fill="#33452b"/>';s+='<rect x="'+(p.x-3).toFixed(1)+'" y="'+(top-16).toFixed(1)+'" width="'+(PW+6)+'" height="16" rx="3" fill="#4a663d"/>';s+='<rect x="'+p.x.toFixed(1)+'" y="'+bot.toFixed(1)+'" width="'+PW+'" height="'+(FLOOR-bot).toFixed(1)+'" fill="#33452b"/>';s+='<rect x="'+(p.x-3).toFixed(1)+'" y="'+bot.toFixed(1)+'" width="'+(PW+6)+'" height="16" rx="3" fill="#4a663d"/>';}s+='<circle cx="'+BX+'" cy="'+state.y.toFixed(1)+'" r="'+R+'" fill="#d4ef8b"/>';s+='<circle cx="'+(BX+4)+'" cy="'+(state.y-3).toFixed(1)+'" r="2.5" fill="#141718"/>';s+='<circle cx="'+(BX-2)+'" cy="'+(state.y+4).toFixed(1)+'" r="4" fill="#b7d877"/>';ui.html('world',s);}
function reset(){state.mode='ready';state.score=0;state.vy=0;state.y=240;state.pipes=[];ui.text('score','0');ui.text('msg','Tippen oder Leertaste zum Start');draw();}
function die(){state.mode='over';if(state.score>state.best)state.best=state.score;ui.text('best','Beststand: '+state.best);ui.text('msg','Game Over · Tippen für Neustart');ui.persist();draw();}
function flap(){if(state.mode==='ready'){state.mode='play';state.pipes=[{x:W+40,gap:gapRand(),passed:false}];state.vy=FLAP;ui.text('msg','');}else if(state.mode==='play'){state.vy=FLAP;}else{reset();}}
function tick(e){var ms=(e&&e.dt)?e.dt:50;if(ms>80)ms=80;var dt=ms/1000;t+=dt;if(state.mode==='ready'){state.y=240+Math.sin(t*2.2)*9;draw();return;}if(state.mode!=='play')return;var i,p;state.vy+=GRAV*dt;state.y+=state.vy*dt;if(state.y<R){state.y=R;state.vy=0;}for(i=0;i<state.pipes.length;i++){state.pipes[i].x-=SPEED*dt;}var last=state.pipes[state.pipes.length-1];if(!last||last.x<W-SPACING)state.pipes.push({x:last?last.x+SPACING:W,gap:gapRand(),passed:false});while(state.pipes.length&&state.pipes[0].x+PW<-8)state.pipes.shift();for(i=0;i<state.pipes.length;i++){p=state.pipes[i];if(!p.passed&&p.x+PW<BX-R){p.passed=true;state.score++;ui.text('score',String(state.score));}}if(state.y+R>=FLOOR){state.y=FLOOR-R;die();return;}for(i=0;i<state.pipes.length;i++){p=state.pipes[i];if(BX+R>p.x&&BX-R<p.x+PW){var top=p.gap-GAP/2,bot=p.gap+GAP/2;if(state.y-R<top||state.y+R>bot){die();return;}}}draw();}
ui.on('field','click',flap);
ui.on('field','keydown',function(e){if(e.key===' '||e.key==='ArrowUp'||e.code==='Space'||e.code==='ArrowUp')flap();});
ui.on('restart','click',function(){reset();});
ui.text('best','Beststand: '+state.best);
reset();
ui.every(50,tick);
